@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=DM+Sans:wght@400;500;600;700;800&display=swap');
:root{--ink:#090b16;--paper:#f0f0f2;--muted:#9a9ba8;--pink:#ff3d77;--cyan:#5be6e2;--yellow:#ffd66b;--panel:rgba(13,15,28,.76);--line:rgba(255,255,255,.13)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--ink);color:var(--paper);font-family:'DM Sans',sans-serif}button,input,select{font:inherit}button{color:inherit}#app{position:relative;width:100%;height:100%;min-height:440px;overflow:hidden;background:#101323}#game{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette,.scanlines{position:absolute;inset:0;pointer-events:none}.vignette{z-index:1;background:radial-gradient(ellipse at 50% 43%,transparent 20%,rgba(4,5,12,.17) 65%,rgba(4,5,12,.72) 130%)}.scanlines{z-index:1;opacity:.12;background:repeating-linear-gradient(0deg,transparent 0 3px,rgba(0,0,0,.2) 4px)}.screen{position:absolute;inset:0;z-index:2;display:none}.screen.active{display:block}.menu-screen{background:linear-gradient(90deg,rgba(7,8,17,.94) 0%,rgba(7,8,17,.78) 38%,rgba(7,8,17,.08) 80%),linear-gradient(0deg,rgba(6,7,14,.62),transparent 30%)}.topbar{position:absolute;top:0;left:0;right:0;height:80px;padding:0 6.2%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.08)}.brand{font:800 21px 'Barlow Condensed',sans-serif;letter-spacing:2px;display:flex;align-items:center;gap:12px}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border:1px solid var(--pink);color:var(--pink);font-size:23px}.brand-light{font-weight:500;color:#b8bac7}.top-meta{color:#c3c4ce;letter-spacing:2px;font:600 10px 'Barlow Condensed',sans-serif;display:flex;align-items:center;gap:9px}.live-dot{width:7px;height:7px;border-radius:50%;background:var(--pink);box-shadow:0 0 12px var(--pink);display:inline-block}.menu-content{position:absolute;left:11.5%;top:19%;width:min(440px,45vw)}.eyebrow{display:flex;align-items:center;gap:10px;font:700 10px 'DM Sans';letter-spacing:2px;color:var(--cyan)}.eyebrow i{width:22px;height:1px;background:var(--cyan);display:inline-block}h1,h2,h3,p{margin:0}h1{font:900 clamp(76px,10vw,145px)/.77 'Barlow Condensed',sans-serif;letter-spacing:-3px;margin:27px 0 22px;text-shadow:0 5px 25px rgba(0,0,0,.15)}h1 em,h2 em{color:var(--pink);font-style:normal}.hero-copy{max-width:330px;color:#c0c1cb;font-size:13px;line-height:1.75}.menu-actions{margin-top:33px;width:275px;display:grid;gap:7px}.primary-btn{border:0;height:54px;padding:0 18px;background:var(--pink);color:white;display:flex;align-items:center;justify-content:space-between;cursor:pointer;font:800 12px 'DM Sans';letter-spacing:1.1px;box-shadow:0 8px 26px rgba(255,61,119,.23);transition:transform .18s,filter .18s}.primary-btn:hover{transform:translateY(-2px);filter:brightness(1.12)}.primary-btn b{font-size:19px}.text-btn{height:39px;padding:0 5px;background:none;border:0;text-align:left;color:#dedee5;cursor:pointer;letter-spacing:1.2px;font:700 10px 'DM Sans';display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.12)}.text-btn span{font-size:16px;color:var(--cyan)}.garage-teaser{display:flex;align-items:center;gap:14px;margin-top:30px;color:#ddd}.teaser-line{height:31px;width:2px;background:var(--pink)}.garage-teaser small{display:block;color:#888b9c;font-size:8px;letter-spacing:1.6px;margin-bottom:3px}.garage-teaser strong{font:700 15px 'Barlow Condensed';letter-spacing:1.5px}.teaser-car{font-size:31px;color:var(--pink);margin-left:10px;transform:scaleX(1.7)}.menu-footer{position:absolute;left:6.2%;right:6.2%;bottom:22px;display:flex;justify-content:space-between;color:#8c8e9b;font:600 9px 'DM Sans';letter-spacing:1.5px}.vertical-jp{position:absolute;right:5.7%;top:34%;writing-mode:vertical-rl;font:700 11px 'DM Sans';letter-spacing:4px;color:rgba(255,255,255,.48)}
.garage-screen{background:linear-gradient(110deg,rgba(7,8,17,.94),rgba(8,10,20,.62) 72%,rgba(8,10,20,.8))}.subhead{position:absolute;top:7%;left:7%;right:7%;display:flex;align-items:center;gap:19px}.back-btn{border:1px solid var(--line);background:rgba(255,255,255,.04);width:40px;height:40px;cursor:pointer;color:var(--cyan);font-size:19px}.subhead small{color:var(--cyan);font:700 9px 'DM Sans';letter-spacing:2px}.subhead h2,.settings-card h2,.pause-card h2{font:800 40px/.95 'Barlow Condensed';letter-spacing:1px;margin-top:5px}.step-label{margin-left:auto;color:#8c8e9b;font:600 9px 'DM Sans';letter-spacing:1.5px}.garage-layout{position:absolute;inset:18% 10% 12%;display:grid;grid-template-columns:1.35fr .85fr;align-items:center;gap:6%}.car-preview{position:relative;min-width:0}.car-preview canvas{width:100%;height:auto;position:relative;z-index:1;filter:drop-shadow(0 26px 26px rgba(0,0,0,.38))}.preview-glow{position:absolute;left:16%;right:10%;bottom:22%;height:23%;background:rgba(255,45,115,.19);filter:blur(38px);border-radius:50%}.preview-spec{display:flex;justify-content:space-between;color:#babcc9;font:700 9px 'DM Sans';letter-spacing:1.4px;margin-top:-3px}.preview-spec b{color:var(--pink)}.car-details{max-width:350px}.car-number{font:700 12px 'Barlow Condensed';color:var(--cyan);letter-spacing:2px}.car-number i{color:#777989;font-style:normal}.car-details h3{font:900 clamp(39px,5vw,68px)/.95 'Barlow Condensed';letter-spacing:1px;margin:10px 0 12px}.car-details p{color:#a9abba;font-size:11px;line-height:1.7;max-width:305px}.stat-list{display:grid;gap:10px;margin:22px 0}.stat-list>div{display:grid;grid-template-columns:48px 1fr 24px;align-items:center;gap:9px;font:700 9px 'DM Sans';color:#b4b6c1}.stat-list b{text-align:right;color:#f3f3f5}.stat-track,.meter-track{height:3px;background:rgba(255,255,255,.13)}.stat-track i,.meter-track i{height:100%;display:block;width:60%;background:var(--pink);box-shadow:0 0 8px rgba(255,61,119,.6)}.car-pager{display:flex;align-items:center;gap:17px;margin-bottom:20px}.car-pager button{width:34px;height:30px;background:transparent;border:1px solid var(--line);font-size:17px;cursor:pointer}.car-pager button:hover{border-color:var(--cyan);color:var(--cyan)}#carDots{display:flex;gap:7px}.car-dot{width:5px;height:5px;border-radius:50%;background:#666}.car-dot.active{background:var(--pink);box-shadow:0 0 8px var(--pink)}.garage-start{width:100%;max-width:280px}.garage-bottom{position:absolute;bottom:22px;left:7%;right:7%;display:flex;justify-content:space-between;color:#858796;font:600 9px 'DM Sans';letter-spacing:1.4px}
.settings-screen,.pause-screen{background:rgba(4,5,12,.67);backdrop-filter:blur(8px);align-items:center;justify-content:center}.settings-screen.active,.pause-screen.active{display:flex}.settings-card,.pause-card{width:min(510px,90vw);padding:34px 40px;background:rgba(13,15,28,.94);border:1px solid rgba(255,255,255,.14);box-shadow:0 30px 90px rgba(0,0,0,.45)}.settings-card>.back-btn{width:auto;height:auto;padding:8px 12px;margin-bottom:28px;font-size:9px;letter-spacing:1px}.settings-card h2,.pause-card h2{font-size:48px;margin:12px 0 7px}.settings-card>p{color:#989aa8;font-size:12px;margin-bottom:22px}.setting-row{min-height:64px;border-top:1px solid rgba(255,255,255,.1);display:grid;grid-template-columns:1fr 145px 48px;align-items:center;gap:14px}.setting-row span b,.setting-row span small{display:block}.setting-row span b{font-size:10px;letter-spacing:1px}.setting-row span small{font-size:9px;color:#8d8f9d;margin-top:4px}.setting-row input{width:100%;accent-color:var(--pink)}.setting-row strong{font-size:10px;text-align:right;color:var(--cyan)}select{background:#171a2a;border:1px solid var(--line);color:white;padding:8px;font-size:9px;letter-spacing:1px}.settings-note{border-top:1px solid rgba(255,255,255,.1);padding-top:17px;margin-top:10px;color:#787b8b;font-size:8px;letter-spacing:1.4px}.settings-note span{color:var(--cyan);margin-left:6px}.pause-card .eyebrow{margin-bottom:20px}.pause-card h2{margin-bottom:28px}.pause-card .primary-btn{width:100%;margin-bottom:7px}.pause-card .text-btn{width:100%}
.hud{position:absolute;z-index:3;inset:0;pointer-events:none}.hud.hidden{display:none}.hud button{pointer-events:auto}.hud-top{position:absolute;top:max(20px,env(safe-area-inset-top));left:24px;right:24px;display:flex;align-items:center;gap:9px}.icon-btn{width:39px;height:39px;border:1px solid rgba(255,255,255,.32);background:rgba(9,11,22,.55);backdrop-filter:blur(8px);font-size:16px;cursor:pointer}.icon-btn:hover{border-color:var(--cyan);color:var(--cyan)}.location{margin-left:8px;display:flex;gap:9px;align-items:center;text-shadow:0 2px 6px #000}.location b,.location small{display:block}.location b{font:800 14px 'Barlow Condensed';letter-spacing:1.5px}.location small{font-size:8px;letter-spacing:1px;color:#c1c3ce}.hud-top .light-btn{margin-left:auto}.mission-card{pointer-events:auto;position:absolute;top:84px;left:24px;display:flex;align-items:center;gap:11px;padding:10px 12px;background:rgba(9,11,22,.68);border-left:2px solid var(--yellow);backdrop-filter:blur(8px);min-width:260px;max-width:330px}.mission-icon{font:700 17px 'Barlow Condensed';color:var(--yellow);border:1px solid rgba(255,214,107,.3);width:31px;height:31px;display:grid;place-items:center}.mission-card>div:nth-child(2){flex:1}.mission-card small,.mission-card b,.mission-card span{display:block}.mission-card small{font:600 7px 'DM Sans';letter-spacing:1px;color:var(--yellow)}.mission-card b{font:700 11px 'DM Sans';margin:3px 0}.mission-card span{font-size:8px;color:#a6a8b4}.mission-card button{border:0;background:transparent;color:var(--yellow);font:800 8px 'DM Sans';cursor:pointer}.hud-right{position:absolute;right:25px;top:22%;text-align:right;text-shadow:0 2px 6px #000}.speed-box>span,.drift-meter>span{display:block;font:700 8px 'DM Sans';letter-spacing:2px;color:#ccd0dc}.speed-box strong{font:800 65px/.95 'Barlow Condensed';letter-spacing:1px}.speed-box i{display:block;font:600 8px 'DM Sans';letter-spacing:1px;color:#adb0bf;font-style:normal}.speed-box i b{color:var(--cyan);font-size:12px;margin-left:4px}.drift-meter{margin-top:18px}.drift-meter strong{font:700 19px 'Barlow Condensed';letter-spacing:1.5px}.drift-meter .meter-track{margin-top:5px;width:105px;margin-left:auto}.drift-meter .meter-track i{background:var(--cyan);box-shadow:0 0 8px var(--cyan);transition:width .2s}.hud-bottom-left{position:absolute;bottom:29px;left:25px}.route-label{display:flex;align-items:center;gap:10px;text-shadow:0 2px 6px #000}.route-pin{font-size:24px;color:var(--pink)}.route-label b,.route-label small{display:block}.route-label b{font:800 12px 'Barlow Condensed';letter-spacing:1.5px}.route-label small{font-size:8px;color:#b7b9c5;letter-spacing:.8px;margin-top:2px}.touch-controls{position:absolute;bottom:max(15px,env(safe-area-inset-bottom));right:22px;left:auto;display:flex;align-items:flex-end;gap:clamp(20px,5vw,70px);pointer-events:none}.steer-group,.action-group{display:flex;align-items:flex-end;gap:8px;pointer-events:auto}.control-btn{pointer-events:auto;touch-action:none;user-select:none;-webkit-user-select:none;cursor:pointer;border:1px solid rgba(255,255,255,.34);background:rgba(15,18,32,.55);backdrop-filter:blur(7px);display:flex;align-items:center;justify-content:center;flex-direction:column;color:white}.control-btn:active,.control-btn.pressed{background:rgba(255,61,119,.72);border-color:#ff8baa;transform:scale(.96)}.steer{width:54px;height:57px;font-size:20px}.action-group .control-btn{height:62px;width:55px}.action-group .control-btn span{font-size:18px}.action-group small{font:700 7px 'DM Sans';letter-spacing:.7px;margin-top:2px}.action-group .gas{height:76px;width:65px;background:rgba(255,61,119,.36);border-color:rgba(255,90,135,.67)}.action-group .brake{border-color:rgba(91,230,226,.5)}.action-group .handbrake{height:52px;width:62px}.action-group .handbrake span{font-size:13px}.key-hint{position:absolute;bottom:18px;left:50%;transform:translateX(-50%);white-space:nowrap;color:rgba(255,255,255,.48);font:600 8px 'DM Sans';letter-spacing:1px}.toast{position:absolute;left:50%;top:23%;transform:translate(-50%,-10px);opacity:0;background:rgba(8,10,20,.88);border:1px solid rgba(91,230,226,.45);padding:12px 18px;font:700 10px 'DM Sans';letter-spacing:1px;transition:.3s;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}#orientationHint{display:none;position:absolute;z-index:9;bottom:5px;left:50%;transform:translateX(-50%);white-space:nowrap;font-size:8px;color:#fff;pointer-events:none}
@media(max-width:700px){.topbar{height:62px;padding:0 20px}.brand{font-size:18px}.top-meta{font-size:8px}.menu-content{left:9%;top:18%;width:80%}h1{font-size:clamp(76px,17vw,116px);margin:23px 0 16px}.hero-copy{max-width:290px;font-size:12px}.menu-actions{margin-top:24px;width:min(270px,85vw)}.garage-teaser{margin-top:20px}.menu-footer{left:20px;right:20px;bottom:14px;font-size:7px}.menu-footer span:nth-child(2){display:none}.vertical-jp{right:7%;top:22%}.subhead{top:5%;left:5%;right:5%;gap:12px}.subhead h2{font-size:32px}.step-label{font-size:7px}.garage-layout{inset:15% 7% 9%;grid-template-columns:1fr;grid-template-rows:auto 1fr;gap:0;align-content:center}.car-preview{width:100%;align-self:end}.car-preview canvas{max-height:34vh}.preview-spec{font-size:7px}.car-details{max-width:none;align-self:start;padding:5px 5px 0}.car-details h3{font-size:43px;margin:5px 0 6px}.car-details p{font-size:10px;max-width:500px}.stat-list{grid-template-columns:repeat(3,1fr);gap:10px;margin:13px 0}.stat-list>div{grid-template-columns:1fr 23px;gap:5px}.stat-track{grid-row:2;grid-column:1}.stat-list b{grid-column:2;grid-row:1}.stat-list span{font-size:7px}.car-pager{position:absolute;top:39%;right:0;margin:0}.garage-start{position:absolute;bottom:-54px;left:0;right:0;max-width:none;height:45px}.garage-bottom{bottom:12px;font-size:7px}.settings-card,.pause-card{padding:25px 22px}.settings-card h2,.pause-card h2{font-size:40px}.setting-row{grid-template-columns:1fr 105px 38px;gap:8px;min-height:59px}.setting-row span b{font-size:9px}.setting-row span small{font-size:8px}.mission-card{top:72px;left:10px;min-width:0;width:230px;padding:8px}.hud-top{top:max(10px,env(safe-area-inset-top));left:10px;right:10px}.icon-btn{width:35px;height:35px}.location b{font-size:12px}.location small{font-size:7px}.hud-right{top:22%;right:12px}.speed-box strong{font-size:54px}.drift-meter{margin-top:10px}.drift-meter .meter-track{width:80px}.hud-bottom-left{bottom:17px;left:12px}.route-label b{font-size:10px}.route-label small{font-size:7px}.touch-controls{left:10px;right:10px;bottom:max(13px,env(safe-area-inset-bottom));justify-content:space-between;gap:0}.steer-group{gap:7px}.steer{width:48px;height:52px}.action-group{gap:6px}.action-group .control-btn{height:53px;width:47px}.action-group .gas{height:65px;width:52px}.action-group .handbrake{width:52px;height:46px}.action-group small{font-size:6px}.key-hint{display:none}.toast{top:30%;font-size:9px;max-width:90vw;white-space:normal;text-align:center}.hud-top{gap:6px}}
@media(max-height:520px) and (orientation:landscape){.menu-content{top:15%}h1{font-size:76px;margin:16px 0}.hero-copy{font-size:10px}.menu-actions{margin-top:12px;gap:2px}.garage-teaser{margin-top:10px}.topbar{height:52px}.garage-layout{inset:15% 9% 9%;grid-template-columns:1.2fr 1fr;grid-template-rows:1fr;gap:5%}.car-preview canvas{max-height:60vh}.car-details h3{font-size:44px}.stat-list{margin:10px 0}.garage-start{position:static}.car-pager{position:static;margin-bottom:10px}.mission-card{top:64px}.touch-controls{bottom:10px}.action-group .control-btn{height:49px}.action-group .gas{height:58px}.hud-right{top:20%}.speed-box strong{font-size:49px}}
@media (orientation:portrait) and (max-width:500px){#orientationHint{display:block;opacity:.7}}

(() => {
  'use strict';
  const canvas = document.getElementById('game'), ctx = canvas.getContext('2d');
  const preview = document.getElementById('carPreview'), pctx = preview.getContext('2d');
  const $ = id => document.getElementById(id);
  const screens = ['menuScreen','garageScreen','settingsScreen','pauseScreen'];
  const cars = [
    {name:'KAZE R-34',cls:'STREET / AWD',desc:'Legenda jalanan dengan keseimbangan sempurna. Dibuat untuk tikungan panjang dan malam tanpa akhir.',power:92,grip:78,drift:86,color:'#35d9db',accent:'#ff416e',shape:1},
    {name:'HAYATE S-15',cls:'TOUGE / RWD',desc:'Ringan, lincah, dan hidup di setiap tikungan. Pilihan para pemburu apex di jalur gunung.',power:78,grip:72,drift:96,color:'#f0eff5',accent:'#ff4d7e',shape:0},
    {name:'AKUMA RX-7',cls:'ROTARY / RWD',desc:'Jantung rotary yang meraung di tengah malam. Mesin responsif untuk drift panjang yang presisi.',power:88,grip:69,drift:92,color:'#f4b044',accent:'#e64163',shape:2},
    {name:'RAIJIN 86',cls:'CLASSIC / RWD',desc:'Klasik yang tak pernah padam. Jinakkan tenaga liar dan jadikan setiap sudut sebagai panggung.',power:73,grip:81,drift:88,color:'#f1f0eb',accent:'#d83c54',shape:3}
  ];
  let selected=0, W=innerWidth,H=innerHeight,dpr=1,last=0,run=false,paused=false,simTime=0, roadScroll=0, skyline=[], particles=[], toastTimer=0;
  const state={speed:0,steer:0,offset:0,score:0,drift:0,distance:0,light:true,camera:0,mission:'delivery',missionActive:false,missionProgress:0,raceTime:0,boost:0};
  const input={gas:false,brake:false,left:false,right:false,handbrake:false};
  const prefersTouch=('ontouchstart' in window)||navigator.maxTouchPoints>0;
  function resize(){W=innerWidth;H=innerHeight;dpr=Math.min(devicePixelRatio||1,1.65);canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);seedCity();drawPreview();}
  function seedCity(){skyline=[];let x=-40;while(x<W+80){let w=24+Math.random()*65,h=45+Math.random()*180;skyline.push({x,w,h,seed:Math.random(),rows:Math.floor(h/13)});x+=w+3}}
  function showScreen(id){screens.forEach(s=>$(s).classList.toggle('active',s===id));}
  function updateCar(){let c=cars[selected];$('carName').textContent=c.name;$('menuCarName').textContent=c.name;$('carClass').textContent=c.cls;$('carDesc').textContent=c.desc;$('carIndex').innerHTML=`0${selected+1} <i>/ 04</i>`;$('powerNum').textContent=c.power;$('gripNum').textContent=c.grip;$('driftNum').textContent=c.drift;$('statPower').style.width=c.power+'%';$('statGrip').style.width=c.grip+'%';$('statDrift').style.width=c.drift+'%';$('carDots').innerHTML=cars.map((_,i)=>`<i class="car-dot ${i===selected?'active':''}"></i>`).join('');drawPreview()}
  function cycleCar(dir){selected=(selected+dir+cars.length)%cars.length;updateCar()}
  function startGame(){showScreen('menuScreen');$('hud').classList.remove('hidden');run=true;paused=false;state.speed=0;state.offset=0;state.steer=0;state.score=0;state.distance=0;state.mission='delivery';state.missionActive=false;state.missionProgress=0;state.raceTime=0;updateMission();showToast('SHIBUYA TERBUKA — JALANAN MENUNGGUMU');initAudio();}
  function pauseGame(){if(!run)return;paused=true;showScreen('pauseScreen')}
  function resume(){paused=false;showScreen('menuScreen')}
  function quit(){run=false;paused=false;$('hud').classList.add('hidden');showScreen('menuScreen')}
  $('startBtn').onclick=()=>showScreen('garageScreen');$('settingsBtn').onclick=()=>showScreen('settingsScreen');$('exitBtn').onclick=()=>showToast('Sampai jumpa di jalanan, pembalap.');
  document.querySelectorAll('[data-back]').forEach(b=>b.onclick=()=>showScreen(b.dataset.back));$('prevCar').onclick=()=>cycleCar(-1);$('nextCar').onclick=()=>cycleCar(1);$('driveBtn').onclick=startGame;
  $('pauseBtn').onclick=pauseGame;$('resumeBtn').onclick=resume;$('quitBtn').onclick=quit;$('pauseSettingsBtn').onclick=()=>showScreen('settingsScreen');
  $('lightBtn').onclick=()=>{state.light=!state.light;$('lightBtn').style.color=state.light?'var(--yellow)':'#858796';showToast(state.light?'LAMPU DEPAN AKTIF':'LAMPU DEPAN MATI')};
